// pages/index.js
import { useEffect, useState, useRef } from "react";
import { io } from "socket.io-client";

export default function Home() {
    const [logs, setLogs] = useState([]);
    const logsEndRef = useRef(null);

    useEffect(() => {
        const socket = io("http://localhost:5000"); // change to use port env var
        socket.on("log", (msg) => setLogs((prev) => [...prev, msg]));

        return () => socket.disconnect();
    }, []);

    // scroll to bottom whenever logs update
    useEffect(() => {
        logsEndRef.current?.scrollIntoView({ behavior: "smooth"});
    }, [logs]);

    return (
        <div className="p-4 font-mono bg-gray-900 text-green-400 h-screen overflow-y-scroll">
            <pre>
                {logs.map((log, index) => (
                    <div key={index}>{log}</div>
                ))}
            </pre>
            <div ref={logsEndRef} />
        </div>
    );
}